import React from 'react';
import type { FC } from 'react';
import { SiteAuthProvider } from '@wix/cli-auth';
import { useProjectModel } from '../../model.js';
import { EnvPull } from './EnvPull.js';

export const EnvPullCommand: FC<{ onComplete?: () => void }> = ({
  onComplete,
}) => {
  const {
    model: { config },
  } = useProjectModel();

  let commandTree = <EnvPull onComplete={onComplete} />;

  if (config.projectType === 'Site') {
    commandTree = (
      <SiteAuthProvider siteId={config.siteId}>{commandTree}</SiteAuthProvider>
    );
  }

  return commandTree;
};
